// Sync Munib Tracker brand assets into screenshot-studio public/.
//
// Source of truth: apps/app/assets/images/ (generated by generate-brand-assets.py
// from repo-root munib-logo.png). Run `pnpm generate:app:brand-assets` first if icons
// are missing or stale.
//
// Usage (repo root):  pnpm sync:screenshot-brand-assets
// Also runs automatically at the end of pnpm seed:screenshot-studio.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const studioRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const repoRoot = path.resolve(studioRoot, "..", "..");
const appImages = path.join(repoRoot, "apps", "app", "assets", "images");
const publicDir = path.join(studioRoot, "public");
const appDir = path.join(studioRoot, "src", "app");

const PAIRS = [
  { src: "icon.png", dest: path.join(publicDir, "app-icon.png") },
  { src: "munib-logo.png", dest: path.join(publicDir, "munib-logo.png") },
  { src: "favicon.png", dest: path.join(appDir, "icon.png") },
  { src: "icon-180.png", dest: path.join(appDir, "apple-icon.png") },
];

function copyOne(rel, dest) {
  const src = path.join(appImages, rel);
  if (!fs.existsSync(src)) {
    console.warn(`  skip (missing): ${src}`);
    return false;
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.copyFileSync(src, dest);
  console.log(`  ${path.relative(repoRoot, src)} → ${path.relative(repoRoot, dest)}`);
  return true;
}

function main() {
  if (!fs.existsSync(appImages)) {
    console.error(`Missing app images dir: ${appImages}`);
    console.error("Run: pnpm generate:app:brand-assets");
    process.exit(1);
  }

  console.log("Syncing Munib Tracker brand assets into screenshot-studio…");
  let ok = 0;
  for (const { src, dest } of PAIRS) {
    if (copyOne(src, dest)) ok += 1;
  }

  if (ok === 0) {
    console.error("No assets copied. Run: pnpm generate:app:brand-assets");
    process.exit(1);
  }

  console.log(`Done (${ok}/${PAIRS.length} files).`);
}

main();
